package com.samadhansetu.controller;
import com.samadhansetu.Service.FacultyProfileService; import com.samadhansetu.dto.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/faculty-profiles") @RequiredArgsConstructor public class FacultyProfileController{private final FacultyProfileService service;@GetMapping("/{id}") public FacultyProfileResponseDto get(@PathVariable Long id){return service.get(id);}@GetMapping("/faculty/{facultyId}") public FacultyProfileResponseDto byFaculty(@PathVariable Long facultyId){return service.getByFaculty(facultyId);}@GetMapping("/university/{universityId}") public List<FacultyProfileResponseDto> byUniversity(@PathVariable Long universityId){return service.byUniversity(universityId);}@GetMapping("/department/{departmentId}") public List<FacultyProfileResponseDto> byDepartment(@PathVariable Long departmentId){return service.byDepartment(departmentId);}@GetMapping("/search") public List<FacultyProfileResponseDto> search(@RequestParam String specialization){return service.searchSpecialization(specialization);}@PutMapping("/{id}") public FacultyProfileResponseDto update(@PathVariable Long id,@RequestBody FacultyProfileRequestDto r){return service.update(id,r);}}
